bug_report:
at -O2, spurious stringop-overflow warning writing to std::vector::back()
g++ -O2 -Wextra -Wall -Werror -Wextra vectorBackWrite.cpp

#include <vector>
#include <stddef.h>
#include <iostream>

extern FILE* f;
void triggerBug(uint64_t start, uint64_t end) {
  if (f && end > start) {
    std::vector<char> data(end - start + 1);
    auto res = fread(&data[0], end-start, 1, f);
    if (res == 1) {
      data.back() = 0;
    }
  }
}

